SELECT p.discharge_status, AVG(i.los) AS average_los, STDDEV(i.los) AS standard_deviation_los, COUNT(CASE WHEN i.los <= 7 THEN 1 END) * 100.0 / NULLIF(COUNT(i.los), 0) AS percentage_of_patients_with_los_less_than_or_equal_to_7_days FROM physionet-data.mimiciv_3_1_hosp.patients p JOIN physionet-data.mimiciv_3_1_icu.icustays i ON p.subject_id = i.subject_id WHERE p.gender = 'M' AND p.anchor_age = 73 AND p.anchor_year_group BETWEEN 68 AND 78 AND p.edregtime IS NOT NULL AND p.edouttime IS NOT NULL GROUP BY p.discharge_status ORDER BY average_los NULLS LAST;